<template><view class="ui11-page"><view class="ui11-nav"><navigator open-type="navigateBack" class="ui11-nav__back">‹</navigator><text class="ui11-nav__title">记录饮食</text><text class="ui11-nav__placeholder"></text></view><view class="form"><view class="ui11-row"><text class="ui11-row__label">用餐时间</text><input v-model="form.eatenAt" class="ui11-input" placeholder="请选择时间"/></view><view class="ui11-row"><text class="ui11-row__label">用餐类型</text><picker :range="types" @change="form.mealType=types[$event.detail.value]"><text class="ui11-row__value">{{form.mealType}}　›</text></picker></view></view><view class="form"><view class="ui11-section-title">添加食物</view><textarea v-model="form.foods" placeholder="请输入食物名称和分量"/><view class="ui11-section-title">饮食备注</view><textarea v-model="form.remark" placeholder="请输入备注"/></view><view class="ui11-fixed-action"><view class="ui11-primary-btn" @click="submit">{{loading?'提交中…':'完成'}}</view></view></view></template>
<script>import { saveDiet } from '@/api/health.js'; export default {data(){return{loading:false,types:['早餐','午餐','晚餐','下午加餐'],form:{eatenAt:'',mealType:'下午加餐',foods:'',remark:''}}},methods:{submit(){if(!this.form.foods)return uni.showToast({title:'请填写食物',icon:'none'});this.loading=true;saveDiet(this.form).then(()=>uni.showToast({title:'保存成功',icon:'success'})).catch(()=>uni.showToast({title:'健康服务暂未接入',icon:'none'})).finally(()=>this.loading=false)}}}</script>
<style lang="scss" scoped>.form{margin-bottom:22rpx;padding:24rpx 12rpx;background:#fff}.ui11-input{flex:1;text-align:right}.ui11-row picker{flex:1;text-align:right}textarea{width:100%;min-height:130rpx;padding:16rpx;box-sizing:border-box;border-radius:12rpx;background:#f6f7f8;font-size:28rpx}</style>
